const PRODUCTION_API='https://bitecode-control-next-level.onrender.com/api';
const configuredApi=import.meta.env.VITE_API_URL?.trim();
const safeConfiguredApi=configuredApi && !/-2\.onrender\.com/i.test(configuredApi) ? configuredApi : '';
const API=import.meta.env.PROD?(safeConfiguredApi||PRODUCTION_API):(safeConfiguredApi||'http://localhost:5000/api');
const ORIGIN=API.replace(/\/api\/?$/,'');
const api=axios.create({baseURL:API,timeout:20000});
const createTabId=()=>{try{return crypto.randomUUID()}catch{return `${Date.now()}-${Math.random().toString(36).slice(2)}`}};
const TAB_ID=(()=>{const name=window.name?.startsWith('bitecode-tab-')?window.name:'';const id=name||`bitecode-tab-${createTabId()}`;const previous=sessionStorage.getItem('bitecode-tab-id');if(previous&&previous!==id){sessionStorage.removeItem('token');sessionStorage.removeItem('user')}window.name=id;sessionStorage.setItem('bitecode-tab-id',id);return id})();
api.interceptors.request.use(c=>{const t=sessionStorage.getItem('token');if(t)c.headers.Authorization=`Bearer ${t}`;c.headers['X-Client-Version']='2.1.0';return c});
api.interceptors.response.use(r=>r,e=>{
  if(!e.response && e.config && !e.config.__retried){
    e.config.__retried=true;
    return new Promise(resolve=>setTimeout(resolve,350)).then(()=>api.request(e.config));
  }
if(e.response?.status===401&&sessionStorage.getItem('token')){sessionStorage.removeItem('token');sessionStorage.removeItem('user');if(!location.pathname.startsWith('/login'))location.href='/login?session=expired'}return Promise.reject(e)});
const getUser=()=>JSON.parse(sessionStorage.getItem('user')||'null');
const money=n=>`₹${Number(n||0).toLocaleString('en-IN')}`;
const dateTime=v=>v?new Date(v).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'}):'Not set';
const inputDate=v=>{if(!v)return'';const d=new Date(v);const pad=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`};
const parseJson=(value,fallback)=>{try{return value?JSON.parse(value):fallback}catch{return fallback}}
function useData(url,initial=[]){const[d,setD]=useState(initial),[loading,setLoading]=useState(true),[error,setError]=useState('');const load=()=>{setLoading(true);return api.get(url).then(r=>{setD(r.data);setError('');return r.data}).catch(e=>{const m=e.response?.data?.message||e.message||'Request failed';setError(m);console.error('API load failed:',url,m);return null}).finally(()=>setLoading(false))};useEffect(()=>{load()},[url]);return[d,loading,load,error]}
function Shell({children,admin=false,judge=false}){const nav=useNavigate(),loc=useLocation(),u=getUser(),[open,setOpen]=useState(false),[unread,setUnread]=useState(0);useEffect(()=>{if(u){api.get('/notifications/unread-count').then(r=>setUnread(r.data?.count||0)).catch(()=>{})}},[u?._id]);const logout=()=>{sessionStorage.removeItem('token');sessionStorage.removeItem('user');nav('/login')};const participant=[['/dashboard','Overview',LayoutDashboard],['/notifications',`Notifications${unread?` (${unread})`:''}`,Bell],['/dashboard/payment','Registration',WalletCards],['/dashboard/team','My Team',Users],['/dashboard/problem','Problems',ClipboardList],['/dashboard/compiler','Online Compiler',Code2],['/dashboard/submission','Submission',FileText],['/dashboard/announcements','Announcements',Megaphone],['/dashboard/certificates','Certificates',FileText],['/dashboard/attendance','My Attendance',CheckCircle2],['/dashboard/results','Results',Trophy],['/feedback','Feedback',Sparkles]];const adminLinks=[['/admin','Control Center',LayoutDashboard],['/admin/operations','Operations Center',Activity],['/admin/event','Events',Layers3],['/admin/participants','Participants',Users],['/admin/teams','Teams',Users],['/admin/payments','Payments',WalletCards],['/admin/problems','Problem Studio',ClipboardList],['/admin/compiler','Coding Lab',Code2],['/admin/submissions','Submissions',FileText],['/admin/judges','Judging',Scale],['/admin/attendance','Attendance',CheckCircle2],['/admin/certificates','Certificates',FileText],['/admin/announcements','Announcements',Megaphone],['/admin/roles','Roles & Access',ShieldCheck],['/admin/website','Website Builder',Globe2],['/admin/audit','Audit Log',ShieldCheck],['/admin/anticheat','Anti-Cheat',ShieldCheck],['/admin/feedback','Feedback',Sparkles]];const judgeLinks=[['/judge','Evaluation Queue',Scale],['/judge/submissions','Submissions',FileText],['/attendance/scan','Attendance Scanner',CheckCircle2],['/notifications',`Notifications${unread?` (${unread})`:''}`,Bell],['/feedback','Feedback',Sparkles]];const fieldLinks=u?.role==='mentor'
? [['/mentor','Mentor Home',LayoutDashboard],['/admin/compiler','Coding Lab',Code2],['/attendance/scan','Attendance Scanner',CheckCircle2],['/feedback','Feedback',Sparkles],['/notifications',`Notifications${unread?` (${unread})`:''}`,Bell]]
: [['/volunteer','Volunteer Home',LayoutDashboard],['/attendance/scan','Attendance Scanner',CheckCircle2],['/feedback','Feedback',Sparkles],['/notifications',`Notifications${unread?` (${unread})`:''}`,Bell]];
const financeLinks=[['/finance','Finance Home',LayoutDashboard],['/admin/payments','Payments',WalletCards],['/notifications',`Notifications${unread?` (${unread})`:''}`,Bell],['/feedback','Feedback',Sparkles]];const links=admin?adminLinks:judge?judgeLinks:(['mentor','volunteer'].includes(u?.role)?fieldLinks:u?.role==='finance'?financeLinks:participant);return <div className="app"><aside className={open?'show':''}><div className="brand"><span className="brandMark">B</span><span>BITECODE<br/><i>CONTROL</i></span></div><div className="workspace"><span>EVENT WORKSPACE</span><b>{admin?'Administrator':judge?'Judge workspace':u?.role==='finance'?'Finance workspace':u?.role==='mentor'?'Mentor workspace':u?.role==='volunteer'?'Volunteer workspace':'Participant workspace'}</b></div><nav>{links.map(([to,label,Icon])=><Link className={loc.pathname===to?'active':''} onClick={()=>setOpen(false)} to={to} key={to}><Icon size={17}/><span>{label}</span>{loc.pathname===to&&<ChevronRight size={15}/>}</Link>)}</nav><div className="sideBottom"><div className="userMini"><div className="avatar">{(u?.name||'U').slice(0,1).toUpperCase()}</div><div><b>{u?.name||'Guest'}</b><small>{u?.role||'participant'}</small></div></div><button className="logout" onClick={logout}><LogOut size={16}/> Sign out</button></div></aside><main><div className="mobilebar"><button onClick={()=>setOpen(!open)}><Menu/></button><div className="brand compact"><span className="brandMark">B</span> BITECODE CONTROL</div></div><div className="pageScroll">{children}</div></main></div>}
function PageHead({eyebrow,title,desc,action}){return <div className="pageHead"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1>{desc&&<p>{desc}</p>}</div>{action}</div>}
function Stat({label,value,meta,icon:Icon}){return <div className="statCard"><div className="statIcon"><Icon size={18}/></div><small>{label}</small><strong>{value}</strong>{meta&&<span>{meta}</span>}</div>}
function Card({children,className=''}){return <section className={'card '+className}>{children}</section>}
function Badge({children,type=''}){return <span className={'badge '+type}>{children}</span>}
function Notice({children,type=''}){return <div className={'notice '+type}>{children}</div>}
function Empty({text}){return <div className="empty"><Layers3 size={22}/><span>{text}</span></div>}
function Modal({title,children,onClose}){return <div className="modalBack"><div className="modal"><div className="modalHead"><div><div className="eyebrow">ADMIN CONTROL</div><h2>{title}</h2></div><button className="iconBtn" onClick={onClose}><X/></button></div>{children}</div></div>}

