 const respond=async(id,action)=>{setSaving(true);try{await api.post('/invitations/'+id+'/respond',{action});reload();reloadInv();setMsg(action==='accept'?'Invitation accepted.':'Invitation rejected.')}catch(e){setMsg(e.response?.data?.message||'Could not respond to invitation')}finally{setSaving(false)}};
 const invite=async e=>{e.preventDefault();setSaving(true);try{const f=new FormData(e.target);await api.post('/teams/'+t._id+'/invite',{email:f.get('email')});e.target.reset();setMsg('Invitation sent.')}catch(e){setMsg(e.response?.data?.message||'Could not send invitation')}finally{setSaving(false)}};
