function qrImage(value,size=320){return `https://api.qrserver.com/v1/create-qr-code/?size=${size}x${size}&margin=10&data=${encodeURIComponent(value)}`}
function AttendanceScanner({onScanned,type='entry'}){
 const[h,setH]=useState(null),[token,setToken]=useState(''),[msg,setMsg]=useState(''),[result,setResult]=useState(null),[busy,setBusy]=useState(false),[camera,setCamera]=useState(false),[scanType,setScanType]=useState(type);
 const scannerRef=React.useRef(null);
 const startingRef=React.useRef(false);
 const mountedRef=React.useRef(true);
 useEffect(()=>{
  mountedRef.current=true;
  api.get('/hackathons/current').then(r=>setH(r.data||null)).catch(e=>setMsg(e.response?.data?.message||'Could not load event.'));
  return()=>{
   mountedRef.current=false;
   const scanner=scannerRef.current;
   scannerRef.current=null;
   if(scanner){scanner.stop().catch(()=>{}).finally(()=>scanner.clear().catch(()=>{}));}
  };
 },[]);
 const submit=async value=>{
  const qr=String(value||'').trim();
  if(!qr||!h||busy)return;
  setBusy(true);setMsg('');
  try{
   const r=await api.post('/attendance/scan',{hackathonId:h._id,qrValue:qr,type:scanType});
   setResult(r.data);setToken('');onScanned?.(r.data);
  }catch(e){setMsg(e.response?.data?.message||'Could not mark attendance.');}
  finally{if(mountedRef.current)setBusy(false);}
 };
 const stopCamera=async()=>{
  const scanner=scannerRef.current;
  scannerRef.current=null;
  if(scanner){try{await scanner.stop();}catch{}try{await scanner.clear();}catch{}}
  if(mountedRef.current)setCamera(false);
 };
 const loadScanner=async()=>{
  if(window.Html5Qrcode)return window.Html5Qrcode;
  await new Promise((resolve,reject)=>{
   const existing=document.querySelector('script[data-h5qr]');
   if(existing){
    if(window.Html5Qrcode){resolve();return;}
    const timer=setInterval(()=>{if(window.Html5Qrcode){clearInterval(timer);clearTimeout(timeout);resolve();}},50);
    const timeout=setTimeout(()=>{clearInterval(timer);reject(new Error('Scanner library did not load. Please check your internet connection.'));},10000);
    return;
   }
   const script=document.createElement('script');
   script.src='https://unpkg.com/html5-qrcode@2.3.8/html5-qrcode.min.js';
   script.async=true;script.crossOrigin='anonymous';script.dataset.h5qr='1';
   script.onload=()=>window.Html5Qrcode?resolve():reject(new Error('Scanner library loaded incorrectly.'));
   script.onerror=()=>reject(new Error('Camera scanner library could not load. Please check your internet connection.'));
   document.head.appendChild(script);
  });
  return window.Html5Qrcode;
 };
 const startCamera=async()=>{
  if(startingRef.current||camera||busy)return;
  startingRef.current=true;setMsg('Starting camera…');setResult(null);
  try{
   if(!window.isSecureContext && location.hostname!=='localhost' && location.hostname!=='127.0.0.1')
    throw new Error('Camera access requires HTTPS. Open the deployed site using its HTTPS URL.');
   if(!navigator.mediaDevices?.getUserMedia)
    throw new Error('This browser does not provide camera access. Try the latest Chrome or Edge.');
   const Html5Qrcode=await loadScanner();
   if(!h?._id)throw new Error('No active hackathon is available.');
   // The scanner element must be visible before html5-qrcode initializes it.
   setCamera(true);
   await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));
   if(!document.getElementById('attendance-reader'))throw new Error('Scanner area is unavailable.');
   const scanner=new Html5Qrcode('attendance-reader',{verbose:false});
   scannerRef.current=scanner;
   let handled=false;
   const onDecoded=async decoded=>{
    if(handled)return;
    handled=true;
    await stopCamera();
    await submit(decoded);
   };
   const config={fps:10,qrbox:{width:Math.min(260,Math.max(180,window.innerWidth-80)),height:Math.min(260,Math.max(180,window.innerWidth-80))},aspectRatio:1};
   await scanner.start({facingMode:'environment'},config,onDecoded,()=>{});
   if(mountedRef.current){setMsg('Camera is active. Point it at the participant QR code.');setCamera(true);}
  }catch(e){
   await stopCamera();
   setMsg(e?.message||'Could not start camera. Allow camera permission and use HTTPS, then try again.');
  }finally{startingRef.current=false;}
 };
 return <Card>
  <div className="sectionTitle"><div><small>QR ATTENDANCE</small><h2>Scan participant</h2><p className="muted">Scan the participant's unique QR. The server verifies the event, participant and scanner role before recording attendance.</p></div><Badge>{scanType}</Badge></div>
  {msg&&<Notice type={result?'success':'error'}>{msg}</Notice>}
  <label className="scannerType">Attendance action<select value={scanType} onChange={e=>setScanType(e.target.value)} disabled={busy||camera}><option value="entry">Event check-in</option><option value="exit">Event check-out</option><option value="workshop">Workshop</option><option value="mentor">Mentor session</option><option value="presentation">Final presentation</option></select></label>
  <div className="scannerBox">
   <div id="attendance-reader" className={camera?'':'scannerHidden'} aria-label="QR camera scanner"></div>
   {!camera&&<div className="scannerPlaceholder"><CheckCircle2 size={34}/><b>Camera scanner ready</b><small>Use the camera on a phone/laptop, or enter the QR value below.</small></div>}
  </div>
  <div className="cardActions">
   <button type="button" className="primary" disabled={busy||camera||startingRef.current} onClick={startCamera}><Code2 size={15}/> {camera?'Camera active':startingRef.current?'Starting camera…':'Start camera'}</button>
   {camera&&<button type="button" className="secondary" onClick={stopCamera}>Stop camera</button>}
  </div>
  <form className="inlineForm" onSubmit={e=>{e.preventDefault();submit(token)}}><input value={token} onChange={e=>setToken(e.target.value)} placeholder="Paste BITEATT token if camera is unavailable"/><button type="submit" className="secondary" disabled={busy||!token.trim()}>Mark attendance</button></form>
  {result&&<Notice type="success"><b>{result.message}</b> · {result.record?.user?.name} · {dateTime(result.record?.at)}</Notice>}
 </Card>
}

