function AdminOperations(){
 const [data,setData]=useState(null),[activity,setActivity]=useState([]),[loading,setLoading]=useState(true),[msg,setMsg]=useState(''),[working,setWorking]=useState(false);
 const load=async()=>{setLoading(true);try{const [ops,act]=await Promise.all([api.get('/admin/operations'),api.get('/admin/live-activity')]);setData(ops.data);setActivity(act.data||[]);setMsg('')}catch(e){setMsg(e.response?.data?.message||'Could not load operations center.')}finally{setLoading(false)}};
 useEffect(()=>{load();const t=setInterval(load,10000);return()=>clearInterval(t)},[]);
 const toggle=async(key,value)=>{setWorking(true);setMsg('');try{if(key==='ai')await api.patch('/admin/ai/settings',{enabled:value});else if(key==='compiler')await api.patch('/compiler/admin/settings',{enabled:value});else await api.patch('/admin/events/'+data.event.id+'/feature',{key,enabled:value});await load()}catch(e){setMsg(e.response?.data?.message||'Could not change the event control.')}finally{setWorking(false)}};
 const changePhase=async status=>{if(status===data.event.status)return;setWorking(true);setMsg('');try{await api.patch('/admin/hackathons/'+data.event.id+'/status',{status,from:data.event.status});await load()}catch(e){setMsg(e.response?.data?.message||'Could not change event phase.')}finally{setWorking(false)}};
 const autoAssign=async()=>{setWorking(true);setMsg('');try{const r=await api.post('/admin/judges/auto-assign');setMsg(`Auto-assignment complete: ${r.data.created} new team assignment(s).`);await load()}catch(e){setMsg(e.response?.data?.message||'Could not auto-assign judges.')}finally{setWorking(false)}};
 const download=async type=>{try{const r=await api.get('/admin/export/'+type,{responseType:'blob'});const url=URL.createObjectURL(r.data);const a=document.createElement('a');a.href=url;a.download=type==='submissions'?'code-submissions.csv':`${type}.csv`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),500)}catch(e){setMsg(e.response?.data?.message||'Could not export data.')}};
 if(loading&&!data)return <Shell admin><PageHead eyebrow="OPERATIONS CENTER" title="Live event control" desc="Monitor the complete hackathon from one operational screen."/><Card><Empty text="Loading operational health…"/></Card></Shell>;
 if(!data?.event)return <Shell admin><PageHead eyebrow="OPERATIONS CENTER" title="Live event control" desc="Create an event before operating the platform."/><Card><Empty text="No active hackathon is configured."/></Card></Shell>;
 const m=data.metrics||{},f=data.features||{};const phases=[['draft','Setup'],['registration','Registration'],['live','Hackathon live'],['submission','Submission'],['judging','Judging'],['results','Results'],['closed','Closed']];
 return <Shell admin><PageHead eyebrow="OPERATIONS CENTER" title="Live event control" desc="A real-time command center for event health, access switches, event phases and judging operations." action={<button className="secondary" onClick={load}><RefreshCw size={14}/> Refresh</button>}/>{msg&&<Notice>{msg}</Notice>}
 <div className="stats"><Stat label="Current phase" value={data.event.phase.label} meta={data.event.status} icon={Activity}/><Stat label="Participants" value={m.participants} meta={`${m.paid} payment-approved`} icon={Users}/><Stat label="Teams" value={m.teams} meta={`${m.confirmedTeams} ready`} icon={Users}/><Stat label="Checked in" value={m.checkedIn??0} meta="Event entry scans" icon={CheckCircle2}/><Stat label="Judging" value={`${m.completedEvaluations}/${m.assignments}`} meta={`${m.unassignedTeams} submitted team(s) unassigned`} icon={Scale}/></div>
 <Card><div className="sectionTitle"><div><small>EVENT LIFECYCLE</small><h2>Move the event through its operational phases</h2></div><SlidersHorizontal size={20}/></div><div className="phaseBar">{phases.map(([key,label])=><button key={key} className={data.event.status===key?'phaseActive':'phaseBtn'} disabled={working} onClick={()=>changePhase(key)}>{label}</button>)}</div><p className="muted">Phase changes are recorded in the audit log. Feature switches below remain independent from the event phase.</p></Card>
 <div className="contentGrid"><Card><div className="sectionTitle"><div><small>LIVE CONTROLS</small><h2>Feature access</h2></div><Gauge size={20}/></div>{[['ai','AI assistant',f.ai],['compiler','Online compiler',f.compiler],['teams','Team formation',f.teams!==false],['submissions','Project submissions',f.submissions!==false],['judging','Judging',f.judging!==false],['announcements','Announcements',f.announcements!==false],['certificates','Certificates',f.certificates!==false],['attendance','QR attendance',f.attendance!==false]].map(([k,label,on])=><div className="toggleLine" key={k}><div><b>{label}</b><small>{on?'Available to authorized users':'Blocked for participant workflows'}</small></div><button className={on?'toggleOn':'toggleOff'} disabled={working} onClick={()=>toggle(k,!on)}>{on?'ON':'OFF'}</button></div>)}</Card>
 <Card><div className="sectionTitle"><div><small>EVENT HEALTH</small><h2>System checks</h2></div></div>{[['Database',data.health?.database],['Judge service',data.health?.judgeService],['JWT authentication',data.health?.jwtConfigured],['AI provider',data.health?.ai],['Upload storage',true]].map(([x,on])=><div className="healthRow" key={x}><span className={on?'healthDot':'healthDot bad'}></span><div><b>{x}</b><small>{on?'Operational':'Configuration required'}</small></div><Badge type={on?'success':'danger'}>{on?'OK':'CHECK'}</Badge></div>)}<div className="opsHint"><CircleAlert size={16}/><span>{m.pendingPayments} payment(s) pending · {m.publishedProblems} published coding problem(s) · {m.audit24h} audit action(s) in 24h.</span></div></Card></div>
 <Card><div className="sectionTitle"><div><small>DATA EXPORT</small><h2>Download event records</h2><p className="muted">Export operational records as CSV for reporting or backup. Secrets and passwords are never exported.</p></div><Download size={20}/></div><div className="exportGrid">{[['participants','Participants'],['teams','Teams'],['submissions','Code submissions'],['evaluations','Evaluations'],['certificates','Certificates'],['attendance','Attendance']].map(([k,l])=><button className="secondary exportBtn" key={k} onClick={()=>download(k)}><Download size={14}/>{l}</button>)}</div></Card>
 <Card><div className="sectionTitle"><div><small>JUDGING AUTOMATION</small><h2>Balanced assignment</h2><p className="muted">Assign eligible teams to active judges while distributing workload evenly. Existing assignments are preserved.</p></div><button className="primary" disabled={working} onClick={autoAssign}><WandSparkles size={16}/> Auto-assign judges</button></div><div className="opsMetrics"><div><b>{m.judges}</b><small>Active judges</small></div><div><b>{m.assignments}</b><small>Total assignments</small></div><div><b>{m.unassignedTeams}</b><small>Unassigned submitted teams</small></div><div><b>{m.completedEvaluations}</b><small>Evaluations completed</small></div></div></Card>
 <Card><div className="sectionTitle"><div><small>LIVE ACTIVITY</small><h2>Recent operational events</h2></div><Clock3 size={20}/></div>{activity.map(x=><div className="listRow" key={x.id}><div><b>{x.action} · {x.entity}</b><small>{x.actor} · {dateTime(x.at)}</small></div><code>{x.meta?.name||x.meta?.key||x.entity}</code></div>)}{!activity.length&&<Empty text="No activity recorded for this event yet."/>}</Card>
 </Shell>
}
function RoleWorkspace({role}){
 const [payments,,reloadPayments]=useData(role==='finance'?'/admin/payments':'/notifications',[]);
 const isFinance=role==='finance';
 const title=isFinance?'Finance Workspace':role==='mentor'?'Mentor Workspace':'Volunteer Workspace';
 const desc=isFinance?'Review registration payments and monitor payment status.':role==='mentor'?'Access the coding lab, attendance tools, and participant support workflows.':'Manage attendance scanning, event support, and assigned volunteer workflows.';
 const actions=isFinance?[
  {to:'/admin/payments',label:'Manage payments',detail:'Review payment records and transaction status',icon:WalletCards},
  {to:'/notifications',label:'Notifications',detail:'Review operational updates',icon:Bell}
 ]:role==='mentor'?[
  {to:'/admin/compiler',label:'Coding lab',detail:'Open coding tools and technical support',icon:Code2},
  {to:'/attendance/scan',label:'Attendance scanner',detail:'Scan participant attendance QR codes',icon:CheckCircle2},
  {to:'/feedback',label:'Feedback',detail:'Review and send event feedback',icon:Sparkles},
  {to:'/notifications',label:'Notifications',detail:'Review updates and announcements',icon:Bell}
 ]:[
  {to:'/attendance/scan',label:'Attendance scanner',detail:'Record participant attendance',icon:CheckCircle2},
  {to:'/feedback',label:'Feedback',detail:'Send event feedback',icon:Sparkles},
  {to:'/notifications',label:'Notifications',detail:'Review event updates',icon:Bell}
 ];
 const paymentRows=Array.isArray(payments)?payments:[];
 return <Shell><PageHead eyebrow="ROLE WORKSPACE" title={title} desc={desc}/>{isFinance&&<div className="statsGrid"><Stat label="Payment records" value={paymentRows.length} meta="Records currently loaded" icon={WalletCards}/><Stat label="Paid" value={paymentRows.filter(x=>x.status==='paid').length} meta="Verified transactions" icon={CheckCircle2}/><Stat label="Pending" value={paymentRows.filter(x=>x.status==='pending').length} meta="Awaiting confirmation" icon={Clock3}/></div>}<div className="roleWorkspaceGrid">{actions.map(({to,label,detail,icon:Icon})=><Link className="card roleActionCard" to={to} key={to}><div className="statIcon"><Icon size={20}/></div><h2>{label}</h2><p className="muted">{detail}</p><span className="roleActionLink">Open workspace <ArrowUpRight size={15}/></span></Link>)}</div>{isFinance&&<Card><div className="sectionTitle"><div><small>PAYMENT OPERATIONS</small><h2>Latest payment records</h2></div><button className="secondary smallBtn" onClick={reloadPayments}>Refresh</button></div>{paymentRows.slice(0,5).map(x=><div className="listRow" key={x._id}><div><b>{x.user?.name||'Participant'}</b><small>{x.user?.email||'No email provided'}</small></div><div><b>{money(x.amount)}</b><small>{x.status||'unknown'}</small></div></div>)}{!paymentRows.length&&<Empty text="No payment records are available yet."/>}</Card>}</Shell>;
}

class AppErrorBoundary extends React.Component{constructor(props){super(props);this.state={error:null}}static getDerivedStateFromError(error){return{error}}componentDidCatch(error,info){console.error('UI error:',error,info)}render(){if(this.state.error)return <div className="authPage"><div className="authCard"><div className="eyebrow">APPLICATION ERROR</div><h1>This page could not be displayed.</h1><p className="muted">{this.state.error?.message||'Unexpected interface error.'}</p><button className="primary" onClick={()=>window.location.reload()}>Reload application</button></div></div>;return this.props.children}}

function App(){const u=getUser();return <Routes><Route path="/" element={<Public/>}/><Route path="/login" element={<Auth/>}/><Route path="/register" element={<Auth register/>}/><Route path="/verify-certificate" element={<VerifyCertificate/>}/><Route path="/reset-password" element={<ResetPassword/>}/><Route path="/dashboard" element={<Guard roles={['participant']}><Dashboard/></Guard>}/><Route path="/dashboard/payment" element={<Guard roles={['participant']}><Payment/></Guard>}/><Route path="/dashboard/team" element={<Guard roles={['participant']}><Team/></Guard>}/><Route path="/dashboard/problem" element={<Guard roles={['participant']}><Problems/></Guard>}/><Route path="/dashboard/compiler" element={<Guard roles={['participant']}><CompilerHome/></Guard>}/><Route path="/dashboard/compiler/playground" element={<Guard roles={['participant','admin','judge','mentor','volunteer']}><CompilerPlayground/></Guard>}/><Route path="/dashboard/compiler/:id" element={<Guard roles={['participant']}><Compiler/></Guard>}/><Route path="/dashboard/submission" element={<Guard roles={['participant']}><Submission/></Guard>}/><Route path="/dashboard/announcements" element={<Guard roles={['participant']}><Announcements/></Guard>}/><Route path="/dashboard/certificates" element={<Guard roles={['participant']}><Certificates/></Guard>}/><Route path="/dashboard/attendance" element={<Guard roles={['participant']}><Attendance/></Guard>}/><Route path="/attendance/scan" element={<Guard roles={['admin','judge','mentor','volunteer']}><AttendanceScanPage/></Guard>}/><Route path="/dashboard/results" element={<Guard roles={['participant']}><Results/></Guard>}/><Route path="/admin" element={<Guard roles={['admin']}><Admin/></Guard>}/><Route path="/admin/event" element={<Guard roles={['admin']}><AdminEvent/></Guard>}/><Route path="/admin/participants" element={<Guard roles={['admin']}><AdminParticipants/></Guard>}/><Route path="/admin/teams" element={<Guard roles={['admin']}><AdminTeams/></Guard>}/><Route path="/admin/payments" element={<Guard roles={['admin','finance']}><AdminPayments/></Guard>}/><Route path="/admin/problems" element={<Guard roles={['admin']}><AdminCompiler/></Guard>}/><Route path="/admin/compiler" element={<Guard roles={['admin','judge','mentor','volunteer']}><AdminCompiler/></Guard>}/><Route path="/admin/submissions" element={<Guard roles={['admin','judge']}><AdminSubmissions/></Guard>}/><Route path="/admin/judges" element={<Guard roles={['admin']}><AdminJudges/></Guard>}/><Route path="/admin/attendance" element={<Guard roles={['admin']}><AdminAttendance/></Guard>}/><Route path="/admin/certificates" element={<Guard roles={['admin']}><AdminCertificates/></Guard>}/><Route path="/admin/announcements" element={<Guard roles={['admin']}><AdminAnnouncements/></Guard>}/><Route path="/admin/roles" element={<Guard roles={['admin']}><Roles/></Guard>}/><Route path="/admin/website" element={<Guard roles={['admin']}><Website/></Guard>}/><Route path="/admin/audit" element={<Guard roles={['admin']}><AdminAudit/></Guard>}/><Route path="/admin/anticheat" element={<Guard roles={['admin']}><AdminAntiCheat/></Guard>}/><Route path="/admin/operations" element={<Guard roles={['admin']}><AdminOperations/></Guard>}/><Route path="/feedback" element={<Guard roles={['participant','admin','judge','mentor','volunteer']}><FeedbackPage/></Guard>}/><Route path="/admin/feedback" element={<Guard roles={['admin']}><AdminFeedback/></Guard>}/><Route path="/notifications" element={<Guard roles={['participant','admin','judge','mentor','volunteer','finance']}><Notifications/></Guard>}/><Route path="/finance" element={<Guard roles={['finance']}><RoleWorkspace role="finance"/></Guard>}/><Route path="/mentor" element={<Guard roles={['mentor']}><RoleWorkspace role="mentor"/></Guard>}/><Route path="/volunteer" element={<Guard roles={['volunteer']}><RoleWorkspace role="volunteer"/></Guard>}/><Route path="/judge" element={<Guard roles={['judge']}><Judge/></Guard>}/><Route path="/judge/submissions" element={<Guard roles={['judge']}><JudgeSubs/></Guard>}/><Route path="*" element={<Navigate to={u?'/dashboard':'/'}/>}/></Routes>}
function Guard({children,roles}){const u=getUser();if(!u)return <Navigate to="/login" replace/>;if(roles&&!roles.includes(u.role)){const destination=u.role==='admin'?'/admin':u.role==='judge'?'/judge':u.role==='finance'?'/finance':u.role==='mentor'?'/mentor':u.role==='volunteer'?'/volunteer':'/dashboard';return <Navigate to={destination} replace/>}return children}
createRoot(document.getElementById("root")).render(
  <AppErrorBoundary>
    <BrowserRouter>
      <App />
      <AIAssistant />
    </BrowserRouter>
  </AppErrorBoundary>
);
